using UnityEngine;

public class MinerController : MonoBehaviour
{
    public LayerMask terrainLayer;
    public float miningRange = 2f;
    public float miningForce = 10f;
    private Camera mainCamera;

    void Start()
    {
        mainCamera = Camera.main;
    }

    void Update()
    {
        if (Input.GetMouseButtonDown(0)) // Left Click
        {
            Ray ray = mainCamera.ScreenPointToRay(Input.mousePosition);
            RaycastHit hit;

            if (Physics.Raycast(ray, out hit, miningRange, terrainLayer))
            {
                MineBlock(hit.transform);
            }
        }
    }

    void MineBlock(Transform target)
    {
        // Visual feedback: Flash white
        target.GetComponent<Renderer>().material.color = Color.white;
        StartCoroutine(FlashEffect(target));

        // Destroy block after delay
        Invoke(nameof(DestroyBlock), 0.1f);
    }

    void DestroyBlock()
    {
        GameObject block = target.gameObject; // Ensure 'target' is accessible
        if (block != null)
        {
            // Spawn mining particles here
            Instantiate(MiningParticles, block.transform.position, Quaternion.identity);
            Destroy(block);

            // Add resource to inventory
            GameManager.Instance.AddResource("LuminaShard", 1);
        }
    }

    System.Collections.IEnumerator FlashEffect(Transform target)
    {
        yield return new WaitForSeconds(0.05f);
        target.GetComponent<Renderer>().material.color = target.GetComponent<Renderer>().material.color;
    }
}
```

