```cpp
/**
 * @file monte_carlo_rectangle_area.cpp
 * @brief Estimates the area of a rectangle using the Monte Carlo method.
 *
 * This program:
 * 1. Prompts the user for the rectangle's side lengths (a, b) and the number of random points.
 * 2. Generates random points uniformly within a bounding square that contains the rectangle.
 * 3. Counts how many points fall inside the rectangle.
 * 4. Uses the ratio of points inside to total points to estimate the rectangle's area.
 *
 * The rectangle is positioned with its lower-left corner at (0, 0).
 */

#include <iostream>
#include <random>
#include <iomanip>
#include <cmath>

/**
 * @brief Estimates the area of a rectangle using the Monte Carlo method.
 *
 * @param a        Length of the rectangle along the x-axis.
 * @param b        Length of the rectangle along the y-axis.
 * @param numPoints Number of random points to generate.
 * @return double  Estimated area of the rectangle.
 */
double estimateRectangleArea(double a, double b, int numPoints) {
    if (a <= 0.0 || b <= 0.0 || numPoints <= 0) {
        throw std::invalid_argument("Invalid input: a, b must be positive and numPoints must be positive.");
    }

    // Use a high-quality random number generator
    std::random_device rd;
    std::mt19937 gen(rd());

    // Uniform distribution for x and y in [0, 1]
    std::uniform_real_distribution<double> dist(0.0, 1.0);

    int pointsInside = 0;

    // We generate points in a unit square [0,1]x[0,1] and scale later.
    // A point (u, v) is inside the rectangle if:
    //   0 <= u*a <= a  and  0 <= v*b <= b
    // Since u, v ∈ [0,1], this simplifies to checking if u <= 1 and v <= 1,
    // which is always true. Instead, we generate points in a bounding box
    // that fully contains the rectangle and count those inside.
    //
    // Simpler approach:
    // Generate points uniformly in the rectangle itself and check if they
    // are within the rectangle? That would always be true.
    //
    // Correct Monte Carlo setup:
    // - Define a bounding box that contains the rectangle.
    //   Here, we can use [0, a] x [0, b] as the bounding box itself.
    //   Then every generated point is inside by definition, which doesn't work.
    //
    // Better setup:
    // - Use a larger bounding box, e.g., [0, 2a] x [0, 2b], and count points
    //   that fall into [0, a] x [0, b].
    //
    // For simplicity and clarity, we'll use a bounding box of size (2a) x (2b),
    // centered such that the rectangle occupies the lower-left quadrant.
    // Rectangle: [0, a] x [0, b]
    // Bounding box: [0, 2a] x [0, 2b]
    // Area of bounding box = 2a * 2b = 4ab
    // Ratio = (points inside rectangle) / (total points)
    // Estimated area = ratio * area_of_bounding_box

    double boundingBoxArea = 4.0 * a * b;

    // Uniform distribution over [0, 2a] and [0, 2b]
    std::uniform_real_distribution<double> distX(0.0, 2.0 * a);
    std::uniform_real_distribution<double> distY(0.0, 2.0 * b);

    for (int i = 0; i < numPoints; ++i) {
        double x = distX(gen);
        double y = distY(gen);

        // Check if point is inside the rectangle [0, a] x [0, b]
        if (x >= 0.0 && x <= a && y >= 0.0 && y <= b) {
            ++pointsInside;
        }
    }

    // Monte Carlo estimate:
    // Estimated Area = (pointsInside / totalPoints) * AreaOfBoundingBox
    double estimatedArea = static_cast<double>(pointsInside) / static_cast<double>(numPoints) * boundingBoxArea;

    return estimatedArea;
}

int main() {
    // Set output precision for better readability
    std::cout << std::fixed << std::setprecision(4);

    double a, b;
    int numPoints;

    // Input rectangle dimensions
    std::cout << "Enter the length of side a (along x-axis): ";
    if (!(std::cin >> a) || a <= 0.0) {
        std::cerr << "Invalid input for side a. Please enter a positive number.\n";
        return 1;
    }

    std::cout << "Enter the length of side b (along y-axis): ";
    if (!(std::cin >> b) || b <= 0.0) {
        std::cerr << "Invalid input for side b. Please enter a positive number.\n";
        return 1;
    }

    // Input number of random points
    std::cout << "Enter the number of random points to generate: ";
    if (!(std::cin >> numPoints) || numPoints <= 0) {
        std::cerr << "Invalid input for number of points. Please enter a positive integer.\n";
        return 1;
    }

    try {
        double estimatedArea = estimateRectangleArea(a, b, numPoints);
        double trueArea = a * b;

        std::cout << "\nMonte Carlo Area Estimation Results:\n";
        std::cout << "-------------------------------------\n";
        std::cout << "Side a: " << a << "\n";
        std::cout << "Side b: " << b << "\n";
        std::cout << "Number of points: " << numPoints << "\n";
        std::cout << "Estimated area: " << estimatedArea << "\n";
        std::cout << "True area:      " << trueArea << "\n";
        std::cout << "Absolute error: " << std::abs(estimatedArea - trueArea) << "\n";
        std::cout << "Relative error: " << (std::abs(estimatedArea - trueArea) / trueArea) * 100.0 << "%\n";
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
        return 1;
    }

    return 0;
}
```

