/**
 * Converts a Roman numeral string to an integer.
 * @param {string} roman - A string representing a Roman numeral.
 * @returns {number} The integer value of the Roman numeral.
 */
const romanToInt = (roman) => {
  const map = {
    'I': 1, 'V': 5, 'X': 10, 'L': 50,
    'C': 100, 'D': 500, 'M': 1000
  };

  let total = 0;
  let prevValue = 0;

  // Iterate from right to left
  for (let i = roman.length - 1; i >= 0; i--) {
    const value = map[roman[i]];
    if (!value) throw new Error(`Invalid Roman numeral character: ${roman[i]}`);

    if (value < prevValue) {
      total -= value;
    } else {
      total += value;
    }
    prevValue = value;
  }

  return total;
};

/**
 * Evaluates the mathematical expression constructed from operators and operands.
 * Supports: %, //, **
 * Precedence: ** (highest), // and % (same, left-to-right), + and - (not in this scope but standard).
 * 
 * @param {string[]} operator - Array of operators (e.g., ['%', '//', '**']).
 * @param {string[]} operand - Array of Roman numeral strings (e.g., ['IV', 'III', 'II', 'V']).
 * @returns {number} The result of the calculation.
 */
const doAlgebra = (operator, operand) => {
  // 1. Validation
  if (!Array.isArray(operator) || !Array.isArray(operand)) {
    throw new Error("Both 'operator' and 'operand' must be arrays.");
  }

  if (operator.length !== operand.length - 1) {
    throw new Error("The number of operators must be exactly one less than the number of operands.");
  }

