    throw new Error(`Invalid operator(s) found: ${invalidOps.join(', ')}. Allowed: ${validOperators.join(', ')}`);
  }

  // 2. Convert Roman numerals to integers
  const numbers = operand.map(roman => {
    const num = romanToInt(roman);
    if (num < 0) throw new Error("Operands must be non-negative Roman numerals.");
    return num;
  });

  // 3. Evaluate Expression
  // We use a stack-based approach to handle precedence manually without external libraries.
  // Strategy: 
  // 1. Parse the expression into tokens (numbers and operators).
  // 2. Handle exponentiation (**), which has the highest precedence.
  // 3. Handle floor division (//) and modulo (%), which have equal precedence and are left-associative.

  let stack = [];
  let i = 0;
  const n = numbers.length;
  const ops = operator;

  // Helper to apply an operator between the top two elements of the stack
  const applyOp = (op) => {
    const b = stack.pop();
    const a = stack.pop();
    let result;

    switch (op) {
      case '**':
        result = Math.pow(a, b);
        break;
      case '//':
        // Floor division. Note: In JS, / returns float. Math.floor handles the floor.
        // For negative numbers, JS Math.floor rounds down (towards -infinity), 
        // while mathematical floor division often implies truncation towards zero or specific math definitions.
        // Assuming standard mathematical floor (towards -infinity) as per Math.floor.
        result = Math.floor(a / b);
        break;
      case '%':
        // Modulo. JS % operator works similarly to floor division for signs.
        result = a % b;
        break;
      default:
        throw new Error(`Unsupported operator: ${op}`);
    }
    stack.push(result);
  };

  // Pass 1: Handle Exponentiation (**)
  // Since ** is right-associative in math but we are processing left-to-right in a linear list,
  // we can simply scan for ** and resolve them immediately because they bind tighter than // or %.
  // However, to be safe with mixed operators like A ** B // C, we must ensure we don't grab the wrong operands.
  // A robust way for this specific limited set is:
  // 1. Resolve all ** first.
  // 2. Resolve remaining // and % from left to right.

  // Let's reconstruct the list of numbers and operators into a single evaluation flow
  // that respects precedence.

  // Create a list of values and operators
  // Example: [4, 3, 2, 5] and ['%', '//', '**']
  // Expression: 4 % 3 // 2 ** 5

  // Step A: Resolve ** first
  // We iterate through the operators. If we find '**', we pop the last two numbers, compute, and push back.
  // We repeat until no '**' remains.
  let currentOps = [...ops];
  let currentNums = [...numbers];

  // Resolve **
  let changed = true;
  while (changed) {
    changed = false;
    for (let j = 0; j < currentOps.length; j++) {
      if (currentOps[j] === '**') {
        const b = currentNums.pop();
        const a = currentNums.pop();
        const res = Math.pow(a, b);
        currentNums.push(res);
        currentOps.splice(j, 1);
        changed = true;
        break; // Restart scan to handle cascading or just continue carefully
      }
    }
  }

  // Step B: Resolve // and % (Left to Right)
  // Now currentNums has fewer elements, and currentOps has only // and %
  for (let j = 0; j < currentOps.length; j++) {
    const op = currentOps[j];
    const b = currentNums.pop();
    const a = currentNums.pop();
    let res;

